package com.quicknotes.app;
import android.app.*;import android.content.*;import android.os.*;import android.webkit.*;import org.json.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
/** Runs only in a separately installed test APK, never in the user release. */
public class NativeTests extends Instrumentation {
 Context context;MainActivity activity;
 void check(boolean condition,String message){if(!condition)throw new AssertionError(message);}
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 JSONObject data(long due)throws Exception{return new JSONObject("{\"version\":1,\"lists\":[{\"id\":\"default\",\"title\":\"Test\",\"updated\":1}],\"items\":[]}").put("items",new JSONArray().put(new JSONObject().put("id","native-alarm-test").put("title","Native alarm verification").put("list","default").put("updated",System.currentTimeMillis()).put("due",due).put("timeEnabled",true).put("urgent",true)));}
 void store(JSONObject d)throws Exception{synchronized(MainActivity.STORE_LOCK){Reminders.write(context,d);Reminders.schedule(context,d);}}
 boolean ringing(){AtomicBoolean playing=new AtomicBoolean();runOnMainSync(()->{AlarmService service=AlarmService.current;playing.set(service!=null&&service.player!=null&&service.player.isPlaying());});return playing.get();}
 void awaitRing(boolean expected,long wait)throws Exception{long end=System.currentTimeMillis()+wait;while(System.currentTimeMillis()<end){if(ringing()==expected)return;Thread.sleep(100);}check(ringing()==expected,"Unexpected alarm audio state, expected "+expected+", service="+AlarmService.current);}
 void awaitNotification(NotificationManager nm,String tag,boolean present)throws Exception{long end=System.currentTimeMillis()+5000;while(System.currentTimeMillis()<end){boolean found=false;for(android.service.notification.StatusBarNotification notice:nm.getActiveNotifications())if(tag.equals(notice.getTag()))found=true;if(found==present)return;Thread.sleep(100);}throw new AssertionError("Notification "+tag+" present="+present+" did not arrive");}
 void confirmDeletion()throws Exception{
  CountDownLatch complete=new CountDownLatch(1);AtomicReference<String> result=new AtomicReference<>();AtomicReference<AlertDialog> dialog=new AtomicReference<>();
  runOnMainSync(()->activity.web.evaluateJavascript("confirm('Delete native test reminder?')",s->{result.set(s);complete.countDown();}));
  long end=System.currentTimeMillis()+5000;while(dialog.get()==null&&System.currentTimeMillis()<end){runOnMainSync(()->dialog.set(activity.lastConfirm));Thread.sleep(100);}
  check(dialog.get()!=null&&dialog.get().isShowing(),"WebView deletion confirmation did not appear");runOnMainSync(()->dialog.get().getButton(AlertDialog.BUTTON_POSITIVE).performClick());check(complete.await(5,TimeUnit.SECONDS),"Confirmation callback did not finish");check("true".equals(result.get()),"Confirmation did not return true");
 }
 @Override public void onStart(){Bundle result=new Bundle();try{context=getTargetContext();activity=(MainActivity)startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();Thread.sleep(1500);confirmDeletion();
  check(Reminders.exactAllowed(context),"Exact alarm permission is not granted");
  // Exact alarm must fire while the activity is backgrounded and play actual alarm audio.
  Bundle progress=new Bundle();progress.putString("stream","Native confirmation passed; scheduling first urgent alarm\n");sendStatus(0,progress);
  JSONObject d=data(System.currentTimeMillis()+4000);store(d);runOnMainSync(()->activity.moveTaskToBack(true));awaitRing(true,15000);
  check(AlarmService.current.player.isLooping(),"Urgent alarm audio is not looping");check(AlarmService.current.wake!=null&&AlarmService.current.wake.isHeld(),"Alarm wakelock is absent");
  // Dismiss stops ringing without completing or cloning the reminder.
  context.startService(AlarmService.command(context,"STOP","native-alarm-test"));awaitRing(false,5000);JSONObject saved=Reminders.read(context);check(saved.getJSONArray("items").length()==1,"Dismiss duplicated reminder");check(!saved.getJSONArray("items").getJSONObject(0).optBoolean("done"),"Dismiss completed reminder unexpectedly");
  // A second firing can be snoozed without changing the reminder ID or source due date.
  d=data(System.currentTimeMillis()+3000);store(d);awaitRing(true,15000);context.startService(AlarmService.command(context,"SNOOZE","native-alarm-test"));awaitRing(false,5000);check(context.getSharedPreferences(Reminders.PREFS,0).getLong("snooze:native-alarm-test",0)>System.currentTimeMillis()+250000,"Snooze did not schedule five minutes");
  // Completing cancels snooze and any future urgent alarm; subsequent deletion cancels it too.
  d=data(System.currentTimeMillis()+3000);d.getJSONArray("items").getJSONObject(0).put("done",true);store(d);Thread.sleep(5000);check(!ringing(),"Completed reminder alarm rang");check(context.getSharedPreferences(Reminders.PREFS,0).getLong("snooze:native-alarm-test",0)==0,"Completion retained snooze");
  d=data(System.currentTimeMillis()+3000);store(d);d.getJSONArray("items").getJSONObject(0).put("deleted",true);store(d);Thread.sleep(5000);check(!ringing(),"Deleted reminder alarm rang");
  // Notification actions complete the original and create an independent next occurrence.
  d=data(System.currentTimeMillis()+3000);d.getJSONArray("items").getJSONObject(0).put("repeat","weekdays").put("notes","Native notes");store(d);awaitRing(true,15000);
  NotificationManager nm=(NotificationManager)context.getSystemService(Context.NOTIFICATION_SERVICE);android.service.notification.StatusBarNotification[] notices=nm.getActiveNotifications();boolean verified=false;for(android.service.notification.StatusBarNotification notice:notices){Notification notification=notice.getNotification();if("Native alarm verification".contentEquals(notification.extras.getCharSequence(Notification.EXTRA_TITLE,""))){check("Native notes".contentEquals(notification.extras.getCharSequence(Notification.EXTRA_TEXT,"")),"Alarm notes are not the notification body");check(notification.actions.length==2,"Notification needs two actions");check("Dismiss".contentEquals(notification.actions[0].title),"Missing Dismiss");check("Mark As Completed".contentEquals(notification.actions[1].title),"Missing completion action");verified=true;}}check(verified,"Alarm notification absent");
  context.startService(AlarmService.command(context,"COMPLETE","native-alarm-test"));awaitRing(false,5000);saved=Reminders.read(context);check(saved.getJSONArray("items").length()==2,"Completion did not create next occurrence");check(saved.getJSONArray("items").getJSONObject(0).getBoolean("done"),"Original should remain completed");JSONObject next=saved.getJSONArray("items").getJSONObject(1);check(!next.getBoolean("done")&&!next.getString("id").equals("native-alarm-test")&&next.getLong("due")>System.currentTimeMillis(),"Invalid recurrence clone");
  // Photos travel in custom listener extras without a visible large icon.
  java.io.File photos=new java.io.File(context.getFilesDir(),"attachments");photos.mkdirs();java.io.File image=new java.io.File(photos,"native-photo");android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(32,32,android.graphics.Bitmap.Config.ARGB_8888);try(java.io.FileOutputStream out=new java.io.FileOutputStream(image)){bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();JSONObject photoItem=data(0).getJSONArray("items").getJSONObject(0);photoItem.put("attachments",new JSONArray().put(new JSONObject().put("id","native-photo").put("mime","image/png")));Reminders.notifyReminder(context,photoItem);boolean hasPhoto=false;for(android.service.notification.StatusBarNotification notice:nm.getActiveNotifications()){if("native-alarm-test".equals(notice.getTag())){check(notice.getNotification().extras.getParcelable("quicknotes.contactPhoto")!=null,"Notification listener photo missing");check(notice.getNotification().getLargeIcon()==null,"Photo unexpectedly visible as large icon");hasPhoto=true;}}check(hasPhoto,"Photo notification absent");
  // Both native ZIP/document and Google snapshot paths use this same section-aware merge.
  JSONObject left=data(0),right=data(0);left.put("sections",new JSONArray().put(new JSONObject().put("id","section-test").put("list","default").put("order",2).put("title","Work").put("updated",2)));JSONObject merged=MainActivity.merge(left,right);check(merged.getJSONArray("sections").length()==1,"Native sync lost sections");
  JSONObject item=merged.getJSONArray("items").getJSONObject(0);long now=System.currentTimeMillis();item.put("deleted",true).put("deletedAt",now-30L*86400000).put("attachments",new JSONArray());Retention.purge(merged,now);check(item.optBoolean("purged")&&!item.has("title")&&!item.has("attachments"),"Expired content was not purged");
  runOnMainSync(()->activity.applyTheme("dark"));check(activity.getWindow().getStatusBarColor()==0xff000000,"Dark theme did not reach system bar");runOnMainSync(()->activity.applyTheme("light"));check(activity.getWindow().getStatusBarColor()==0xfff2f2f7,"Light theme did not reach system bar");
  JSONObject widgets=data(0);JSONArray wi=widgets.getJSONArray("items");wi.put(new JSONObject().put("id","widget-early").put("list","default").put("title","Early").put("updated",1).put("due",1000).put("flag",true));wi.put(new JSONObject().put("id","widget-late").put("list","default").put("title","Late").put("updated",1).put("due",2000));wi.put(new JSONObject().put("id","widget-done").put("list","default").put("title","Done").put("updated",1).put("done",true).put("due",500));store(widgets);
  java.util.List<JSONObject> wr=ReminderWidget.rows(context,"all");check(wr.size()==3&&wr.get(0).optString("id").equals("widget-early")&&wr.get(2).optLong("due")==0,"Widget due ordering or completed filtering failed");check(ReminderWidget.rows(context,"scheduled").size()==2,"Widget scheduled filter failed");check(ReminderWidget.rows(context,"flagged").size()==1,"Widget flagged filter failed");check(ReminderWidget.rows(context,"default").size()==3,"Widget user list failed");check(ReminderWidget.rows(context,"missing").isEmpty(),"Widget invalid list leaked reminders");
  runOnMainSync(()->{android.widget.RemoteViews r=new android.widget.RemoteViews(context.getPackageName(),R.layout.reminder_widget);check(r.apply(context,null)!=null,"Widget layout cannot inflate");});
  result.putString("stream","Native alarm and confirmation tests passed\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable error){result.putString("stream","FAILED: "+android.util.Log.getStackTraceString(error));finish(Activity.RESULT_CANCELED,result);}finally{if(activity!=null)runOnMainSync(()->activity.finish());}}
}
